const routes = [
  {
    "when": "selected_workflow == 'development_full'",
    "then": "development_full_workflow"
  },
  {
    "when": "selected_workflow == 'development_shortened'",
    "then": "development_shortened_workflow"
  },
  {
    "when": "selected_workflow == 'development_fast_track'",
    "then": "development_fast_track_workflow"
  },
  {
    "default": "development_full_workflow"
  }
];
const state = $json;

function toJsExpression(expr) {
  return String(expr)
    .replace(/\band\b/g, '&&')
    .replace(/\bor\b/g, '||')
    .replace(/\bnot\b/g, '!')
    .replace(/\bTrue\b/g, 'true')
    .replace(/\bFalse\b/g, 'false')
    .replace(/\bNone\b/g, 'null');
}

function evaluate(expr) {
  const keys = Object.keys(state);
  const values = Object.values(state);
  try {
    return Boolean(Function(...keys, `return (${toJsExpression(expr)});`)(...values));
  } catch (error) {
    return false;
  }
}

let nextStep = null;
for (const route of routes) {
  if (route.when && evaluate(route.when)) {
    nextStep = route.then;
    break;
  }
  if (!route.when && route.default && nextStep === null) {
    nextStep = route.default;
  }
}

return [{ json: { ...state, next_step: nextStep } }];
